import React, { useState, useEffect, useRef } from "react";
import { useAuth } from "../context/AuthContext";
import { userAPI, petsAPI, adminAPI } from "../services/api";
import { useNavigate } from "react-router-dom";

// Helper function to get full image URL
const getImageUrl = (imagePath) => {
  if (!imagePath) return "/default-pet.png";
  if (imagePath.startsWith("http")) return imagePath;
  return `http://localhost:8000${imagePath}`;
};

const AdminDashboard = () => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  console.log("AdminDashboard rendered. User:", user);

  // State management
  const [activeTab, setActiveTab] = useState("dashboard");
  const [activePendingTab, setActivePendingTab] = useState("lost-reports"); // Sub-tab for pending requests
  const [activeRecordsTab, setActiveRecordsTab] = useState("all-lost"); // Sub-tab for all records
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [successMessage, setSuccessMessage] = useState("");
  const [isDarkMode, setIsDarkMode] = useState(() => {
    // Load theme preference from localStorage
    const savedTheme = localStorage.getItem("adminTheme");
    return savedTheme === "dark";
  });

  // Dashboard Stats (comprehensive)
  const [dashboardStats, setDashboardStats] = useState(null);

  // Pending Requests (all types)
  const [pendingLostReports, setPendingLostReports] = useState([]);
  const [pendingFoundReports, setPendingFoundReports] = useState([]);
  const [pendingAdoptionRequests, setPendingAdoptionRequests] = useState([]);
  const [pendingAdoptionPosts, setPendingAdoptionPosts] = useState([]);

  // All Records by Status
  const [allLostPets, setAllLostPets] = useState([]);
  const [allFoundPets, setAllFoundPets] = useState([]);
  const [allAdoptedPets, setAllAdoptedPets] = useState([]);
  const [allAvailablePets, setAllAvailablePets] = useState([]);
  const [allAdoptionRequests, setAllAdoptionRequests] = useState([]); // All adoption requests (approved, rejected, pending)
  const [allAdoptionPosts, setAllAdoptionPosts] = useState([]); // All adoption posts
  
  // Feedback management
  const [allFeedbacks, setAllFeedbacks] = useState([]);
  const [feedbackForm, setFeedbackForm] = useState({ name: "", email: "", message: "" });
  const [feedbackFormErrors, setFeedbackFormErrors] = useState({});
  const [expandedFeedbacks, setExpandedFeedbacks] = useState({});

  // Search and Filter
  const [searchQuery, setSearchQuery] = useState("");
  const [filterType, setFilterType] = useState("all");
  const [filterStatus, setFilterStatus] = useState("all");
  const [filterGender, setFilterGender] = useState("");
  const [filterBreed, setFilterBreed] = useState("");
  const [filterLocation, setFilterLocation] = useState("");
  const [filterReportStatus, setFilterReportStatus] = useState("accepted");
  const [searchResults, setSearchResults] = useState([]);
  const [searchLoading, setSearchLoading] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);

  // Notifications
  const [notifications, setNotifications] = useState([]);
  const [showNotifications, setShowNotifications] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);
  const notificationRef = useRef(null);

  // Detail Modal
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [selectedItem, setSelectedItem] = useState(null);
  const [detailLoading, setDetailLoading] = useState(false);
  const [modalType, setModalType] = useState(""); // 'report' or 'adoption'

  // Profile Dropdown
  const [showProfileDropdown, setShowProfileDropdown] = useState(false);

  // Notification Detail Modal
  const [showNotificationModal, setShowNotificationModal] = useState(false);
  const [selectedNotification, setSelectedNotification] = useState(null);

  // Profile Edit State
  const [profileData, setProfileData] = useState({
    first_name: "",
    last_name: "",
    email: "",
    phone_no: "",
    address: "",
    city: "",
    state: "",
    pincode: "",
    gender: "",
    profile_picture: null,
  });
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [profileImage, setProfileImage] = useState(null);
  const [profileImagePreview, setProfileImagePreview] = useState(null);
  const [submitLoading, setSubmitLoading] = useState(false);

  // Check if user is admin
  useEffect(() => {
    console.log("Admin check - User role:", user?.role);
    if (user && user.role !== "admin") {
      console.log("Not admin, redirecting to /dashboard");
      navigate("/dashboard");
    }
  }, [user, navigate]);

  // Load initial data
  useEffect(() => {
    console.log("Load data effect - User role:", user?.role);
    if (user?.role === "admin") {
      console.log("Loading admin data...");
      loadAllData();
    }
  }, [user]);

  // Auto-hide messages
  useEffect(() => {
    if (error) {
      const timer = setTimeout(() => setError(""), 2000);
      return () => clearTimeout(timer);
    }
  }, [error]);

  useEffect(() => {
    if (successMessage) {
      const timer = setTimeout(() => setSuccessMessage(""), 2000);
      return () => clearTimeout(timer);
    }
  }, [successMessage]);
  
  // Handle outside clicks for notification dropdown
  useEffect(() => {
    const handleOutsideClick = (event) => {
      // Close notification dropdown if clicked outside
      if (
        showNotifications &&
        notificationRef.current &&
        !notificationRef.current.contains(event.target)
      ) {
        setShowNotifications(false);
      }
    };

    document.addEventListener("mousedown", handleOutsideClick);
    return () => {
      document.removeEventListener("mousedown", handleOutsideClick);
    };
  }, [showNotifications]);

  // Fetch feedback
  const fetchFeedbacks = async () => {
    try {
      const API_BASE = "http://localhost:8000";
      const url = `${API_BASE}/api/feedbacks/`;
      
      const response = await fetch(url, {
        headers: {
          Authorization: `Bearer ${user.token}`,
        },
      });
      
      if (!response.ok) {
        throw new Error("Failed to fetch feedback data");
      }
      
      const data = await response.json();
      setAllFeedbacks(
        data.sort(
          (a, b) => new Date(b.created_at) - new Date(a.created_at)
        )
      );
    } catch (error) {
      console.error("Error fetching feedbacks:", error);
      setError("Could not load community feedback. Please try again later.");
    }
  };

  // Handle feedback submission
  const handleFeedbackSubmit = async (e) => {
    e.preventDefault();
    
    // Basic validation
    const errors = {};
    if (!feedbackForm.name.trim()) errors.name = "Name is required";
    if (!feedbackForm.email.trim()) errors.email = "Email is required";
    if (!/\S+@\S+\.\S+/.test(feedbackForm.email)) errors.email = "Valid email is required";
    if (!feedbackForm.message.trim()) errors.message = "Message is required";
    
    if (Object.keys(errors).length > 0) {
      setFeedbackFormErrors(errors);
      return;
    }
    
    try {
      const API_BASE = "http://localhost:8000";
      const url = `${API_BASE}/api/feedbacks/`;
      
      const response = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${user.token}`,
        },
        body: JSON.stringify({
          name: feedbackForm.name,
          email: feedbackForm.email,
          message: feedbackForm.message,
        }),
      });
      
      if (!response.ok) {
        throw new Error("Failed to submit feedback");
      }
      
      // Reset form and fetch updated feedbacks
      setFeedbackForm({ name: "", email: "", message: "" });
      setFeedbackFormErrors({});
      setSuccessMessage("Feedback submitted successfully!");
      fetchFeedbacks();
      
    } catch (error) {
      console.error("Error submitting feedback:", error);
      setError("Failed to submit feedback. Please try again.");
    }
  };
  
  const loadAllData = async () => {
    setLoading(true);
    try {
      // Load all data in parallel for much faster performance
      await Promise.all([
        loadDashboardStats(),
        loadPendingReports(),
        loadPendingAdoptions(),
        loadAllPets(),
        loadAllAdoptionData(),
        loadNotifications(),
        fetchFeedbacks(),
      ]);
    } catch (err) {
      console.error("Error loading admin data:", err);
      setError("Failed to load dashboard data");
    } finally {
      setLoading(false);
    }
  };

  const loadDashboardStats = async () => {
    try {
      const response = await adminAPI.getComprehensiveDashboardStats();
      console.log("Dashboard stats response:", response.data);
      if (response.data.success) {
        setDashboardStats(response.data.stats);
      }
    } catch (err) {
      console.error("Error loading stats:", err);
    }
  };

  const loadPendingReports = async () => {
    try {
      console.log("Loading pending reports from admin API...");
      const response = await adminAPI.getPendingReports();
      console.log("Pending reports response:", response.data);

      if (response.data.success) {
        const reports = response.data.reports || [];
        console.log("Total pending reports:", reports.length);

        // Filter by status field (lost/found)
        const lost = reports.filter((r) => r.status === "lost");
        const found = reports.filter((r) => r.status === "found");

        console.log(
          "Lost reports:",
          lost.length,
          "Found reports:",
          found.length
        );

        setPendingLostReports(lost);
        setPendingFoundReports(found);
      }
    } catch (err) {
      console.error("Error loading pending reports:", err);
      console.error("Error details:", err.response?.data);
    }
  };

  const loadPendingAdoptions = async () => {
    try {
      // Load pending adoption requests and posts in parallel
      const [response, postsResponse] = await Promise.all([
        adminAPI.filterAdoptionRequests({ status: "pending" }),
        adminAPI.getPendingAdoptionPostsNew(),
      ]);

      if (response.data.success) {
        setPendingAdoptionRequests(response.data.adoptions || []);
      }

      if (postsResponse.data && postsResponse.data.success) {
        setPendingAdoptionPosts(postsResponse.data.posts || []);
      }
    } catch (err) {
      console.error("Error loading pending adoptions:", err);
    }
  };

  const loadAllPets = async () => {
    try {
      console.log("Loading all accepted pets in parallel...");

      // Load all pet statuses in parallel for faster performance
      const [lostResponse, foundResponse, adoptedResponse, availableResponse] =
        await Promise.all([
          adminAPI.getAllPetsByStatus("lost"),
          adminAPI.getAllPetsByStatus("found"),
          adminAPI.getAllPetsByStatus("adopted"),
          adminAPI.getAllPetsByStatus("available"),
        ]);

      if (lostResponse.data.success) {
        setAllLostPets(lostResponse.data.pets || []);
        console.log(
          `✅ Loaded ${lostResponse.data.pets?.length || 0} accepted lost pets`
        );
      }

      if (foundResponse.data.success) {
        setAllFoundPets(foundResponse.data.pets || []);
        console.log(
          `✅ Loaded ${
            foundResponse.data.pets?.length || 0
          } accepted found pets`
        );
      }

      if (adoptedResponse.data.success) {
        setAllAdoptedPets(adoptedResponse.data.pets || []);
        console.log(
          `✅ Loaded ${
            adoptedResponse.data.pets?.length || 0
          } accepted adopted pets`
        );
      }

      if (availableResponse.data.success) {
        setAllAvailablePets(availableResponse.data.pets || []);
        console.log(
          `✅ Loaded ${
            availableResponse.data.pets?.length || 0
          } accepted available pets`
        );
      }
    } catch (err) {
      console.error("Error loading all pets:", err);
    }
  };

  const loadAllAdoptionData = async () => {
    try {
      // Load adoption requests and posts in parallel
      const [requestsResponse, postsResponse] = await Promise.all([
        adminAPI.filterAdoptionRequests({ status: "all" }),
        adminAPI.getAllAdoptionPosts("all"),
      ]);

      if (requestsResponse.data.success) {
        setAllAdoptionRequests(requestsResponse.data.adoptions || []);
      }

      if (postsResponse.data.success) {
        setAllAdoptionPosts(postsResponse.data.posts || []);
      }
    } catch (err) {
      console.error("Error loading all adoption data:", err);
    }
  };

  const loadNotifications = async () => {
    try {
      const response = await adminAPI.getNotifications();
      if (response.data.success) {
        setNotifications(response.data.notifications || []);
        const unread = response.data.notifications.filter(
          (n) => !n.is_read
        ).length;
        setUnreadCount(unread);
      }
    } catch (err) {
      console.error("Error loading notifications:", err);
    }
  };
  
  const handleNotificationDropdownToggle = () => {
    setShowNotifications(!showNotifications);
  };

  const handleNotificationClick = async (notification) => {
    try {
      // Mark notification as read
      await adminAPI.markNotificationRead(notification.id);

      // Update local state
      const updatedNotifications = notifications.map((n) =>
        n.id === notification.id ? { ...n, is_read: true } : n
      );
      setNotifications(updatedNotifications);

      // Update unread count
      const newUnreadCount = updatedNotifications.filter(
        (n) => !n.is_read
      ).length;
      setUnreadCount(newUnreadCount);

      // Show notification details in modal
      setSelectedNotification({ ...notification, is_read: true });
      setShowNotificationModal(true);
      setShowNotifications(false); // Close the dropdown
    } catch (err) {
      console.error("Error marking notification as read:", err);
    }
  };

  const handleApproveReport = async (reportId) => {
    try {
      setLoading(true);
      await adminAPI.approveReport(reportId);
      setSuccessMessage("Report approved successfully!");
      await loadAllData();
      setShowDetailModal(false);
    } catch (err) {
      setError(err.response?.data?.error || "Failed to approve report");
    } finally {
      setLoading(false);
    }
  };

  const handleRejectReport = async (reportId) => {
    try {
      setLoading(true);
      await adminAPI.rejectReport(reportId);
      setSuccessMessage("Report rejected successfully!");
      await loadAllData();
      setShowDetailModal(false);
    } catch (err) {
      setError(err.response?.data?.error || "Failed to reject report");
    } finally {
      setLoading(false);
    }
  };

  // Profile Management Functions
  const loadProfile = async () => {
    try {
      const response = await userAPI.getUserDetails();
      if (response.data.success) {
        const userData = response.data.user;
        setProfileData({
          first_name: userData.first_name || "",
          last_name: userData.last_name || "",
          email: userData.email || "",
          phone_no: userData.phone_no || "",
          address: userData.address || "",
          city: userData.city || "",
          state: userData.state || "",
          pincode: userData.pincode || "",
          gender: userData.gender || "",
          profile_picture: userData.profile_picture,
        });

        if (userData.profile_picture) {
          setProfileImagePreview(getImageUrl(userData.profile_picture));
        }
      }
    } catch (err) {
      console.error("Error loading profile:", err);
    }
  };

  const handleProfileImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setProfileImage(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setProfileImagePreview(reader.result);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleProfileSubmit = async (e) => {
    e.preventDefault();
    setSubmitLoading(true);
    setError("");
    setSuccessMessage("");

    try {
      const formData = new FormData();
      Object.keys(profileData).forEach((key) => {
        if (key !== "profile_picture" && profileData[key]) {
          formData.append(key, profileData[key]);
        }
      });

      if (profileImage) {
        formData.append("profile_picture", profileImage);
      }

      const response = await userAPI.updateProfile(formData);
      if (response.data.success) {
        setSuccessMessage("Profile updated successfully!");
        setIsEditingProfile(false);
        setProfileImage(null); // Reset the file input
        await loadProfile();
      }
    } catch (err) {
      setError(err.response?.data?.error || "Failed to update profile");
    } finally {
      setSubmitLoading(false);
    }
  };

  const handleSearch = async () => {
    setSearchLoading(true);
    setHasSearched(true);
    try {
      const filters = {
        query: searchQuery,
        type: filterType,
        status: filterStatus,
        breed: filterBreed,
        location: filterLocation,
        gender: filterGender,
        report_status: filterReportStatus,
      };

      console.log("Searching with filters:", filters);
      const response = await adminAPI.searchPets(filters);
      console.log("Search response:", response.data);

      if (response.data.success) {
        setSearchResults(response.data.pets || []);
      }
    } catch (err) {
      console.error("Error searching pets:", err);
      setError("Failed to search pets");
      setSearchResults([]);
    } finally {
      setSearchLoading(false);
    }
  };

  const handleProfileInputChange = (e) => {
    const { name, value } = e.target;
    setProfileData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  // Toggle theme function
  const toggleTheme = () => {
    const newTheme = !isDarkMode;
    setIsDarkMode(newTheme);
    localStorage.setItem("adminTheme", newTheme ? "dark" : "light");
  };

  // Load profile when profile tab is active
  useEffect(() => {
    if (activeTab === "profile" && user?.role === "admin") {
      loadProfile();
    }
  }, [activeTab, user]);

  const handleApproveAdoption = async (adoptionId) => {
    try {
      setLoading(true);
      await adminAPI.approveAdoption(adoptionId);
      setSuccessMessage("Adoption request approved successfully!");
      await loadAllData();
      setShowDetailModal(false);
    } catch (err) {
      setError(err.response?.data?.error || "Failed to approve adoption");
    } finally {
      setLoading(false);
    }
  };

  const handleRejectAdoption = async (adoptionId) => {
    try {
      setLoading(true);
      await adminAPI.rejectAdoption(adoptionId);
      setSuccessMessage("Adoption request rejected successfully!");
      await loadAllData();
      setShowDetailModal(false);
    } catch (err) {
      setError(err.response?.data?.error || "Failed to reject adoption");
    } finally {
      setLoading(false);
    }
  };

  const viewDetails = (item, type) => {
    setSelectedItem(item);
    setModalType(type);
    setShowDetailModal(true);
  };

  const handleLogout = () => {
    logout();
    navigate("/login");
  };

  return (
    <div className={isDarkMode ? "dark" : ""}>
      <div
        className={`min-h-screen transition-colors duration-300 ${
          isDarkMode
            ? "bg-gradient-to-br from-gray-900 via-purple-900 to-indigo-900"
            : "bg-gradient-to-br from-purple-50 via-indigo-50 to-pink-50"
        }`}
      >
        {/* Header - Purple Gradient Theme */}
        <header
          className={`sticky top-0 z-50 backdrop-blur-sm shadow-lg border-b transition-colors duration-300 ${
            isDarkMode
              ? "bg-gradient-to-r from-slate-900/95 to-blue-900/95 border-blue-700"
              : "bg-gradient-to-r from-purple-300 to-purple-700 border-purple-400"
          }`}
        >
          <div className="w-full px-6 py-4">
            <div className="flex items-center justify-between gap-4">
              <div className="flex items-center gap-3">
                <div className="text-2xl font-bold">
                  <span className="text-white">pet</span>
                  <span className="text-purple-700">rescue</span>
                  <span className="text-white ml-2">- ADMIN</span>
                </div>
              </div>
              <div className="flex-1 text-center">
                <span className="text-lg font-semibold text-white">
                  ADMIN PANEL: {user?.username?.toUpperCase() || "ADMINUSER"}
                </span>
              </div>
              <div className="flex items-center gap-4">
                {/* Refresh Button */}
                <button
                  className="p-2 rounded-full hover:bg-purple-700 transition-all duration-300 disabled:opacity-50"
                  onClick={loadAllData}
                  disabled={loading}
                  title="Refresh Data"
                >
                  <span className="material-icons text-white">refresh</span>
                </button>

                {/* Theme Toggle Button */}
                <button
                  className="p-2 rounded-full hover:bg-purple-700 transition-all duration-300"
                  onClick={toggleTheme}
                  title={
                    isDarkMode ? "Switch to Light Mode" : "Switch to Dark Mode"
                  }
                >
                  <span className="material-icons text-white">
                    {isDarkMode ? "light_mode" : "dark_mode"}
                  </span>
                </button>

                {/* Notifications */}
                <div className="relative" ref={notificationRef}>
                  <button
                    className="p-2 rounded-full hover:bg-purple-700 transition-all duration-300 relative"
                    onClick={handleNotificationDropdownToggle}
                  >
                    <span className="material-icons text-white">
                      notifications
                    </span>
                    {unreadCount > 0 && !showNotifications && (
                      <span className="absolute -top-1 -right-1 bg-pink-500 text-white text-xs font-bold rounded-full w-5 h-5 flex items-center justify-center animate-pulse">
                        {unreadCount}
                      </span>
                    )}
                  </button>

                  {showNotifications && (
                    <div className="absolute right-0 mt-2 w-96 bg-white dark:bg-slate-800 rounded-2xl shadow-2xl border border-purple-200 dark:border-slate-600 overflow-hidden z-50 max-h-[500px] flex flex-col">
                      <div className="flex items-center justify-between p-4 bg-gradient-to-r from-purple-600 to-indigo-600 dark:from-slate-700 dark:to-slate-600 border-b border-purple-500 dark:border-slate-500">
                        <h3 className="text-white font-semibold text-lg">
                          Notifications
                        </h3>
                        <button
                          className="text-white hover:bg-white/20 rounded-full p-1 transition-colors"
                          onClick={(e) => {
                            e.stopPropagation();
                            setShowNotifications(false);
                          }}
                        >
                          <span className="text-2xl leading-none">×</span>
                        </button>
                      </div>
                      <div className="overflow-y-auto flex-1">
                        {notifications.length === 0 ? (
                          <div className="flex flex-col items-center justify-center py-12 text-gray-400">
                            <span className="material-icons text-6xl mb-2">
                              notifications_none
                            </span>
                            <p className="text-sm">No notifications yet</p>
                          </div>
                        ) : (
                          notifications.map((notif) => (
                            <div
                              key={notif.id}
                              className={`p-4 border-b border-purple-200 hover:bg-purple-100 transition-colors cursor-pointer ${
                                notif.is_read
                                  ? "bg-slate-50"
                                  : "bg-purple-50/50"
                              }`}
                              onClick={() => handleNotificationClick(notif)}
                            >
                              <div className="flex items-start justify-between gap-3">
                                <div className="flex-1">
                                  <p
                                    className={`text-sm ${
                                      notif.is_read
                                        ? "text-gray-600"
                                        : "text-gray-800 font-bold"
                                    }`}
                                  >
                                    {notif.message}
                                  </p>
                                  <span className="text-xs text-gray-400 mt-2 block">
                                    {new Date(
                                      notif.created_at
                                    ).toLocaleDateString()}
                                  </span>
                                </div>
                              </div>
                            </div>
                          ))
                        )}
                      </div>
                    </div>
                  )}
                </div>

                {/* Profile Menu */}
                <div className="relative">
                  <button
                    className="w-10 h-10 rounded-full bg-gradient-to-br from-purple-600 to-indigo-600 text-white font-bold text-lg flex items-center justify-center hover:shadow-lg transition-all duration-300 hover:scale-110"
                    onClick={() => setShowProfileDropdown((prev) => !prev)}
                  >
                    {user?.username?.charAt(0).toUpperCase() || "A"}
                  </button>
                  {showProfileDropdown && (
                    <div className="absolute right-0 mt-2 w-48 bg-gradient-to-br from-white to-purple-50 rounded-xl shadow-xl border-2 border-purple-200 overflow-hidden z-50">
                      <button
                        className="w-full px-4 py-3 text-left hover:bg-purple-100 transition-colors text-gray-700 dark:text-gray-200 hover:text-purple-600 font-medium"
                        onClick={() => {
                          setActiveTab("profile");
                          setShowProfileDropdown(false);
                        }}
                      >
                        Edit Profile
                      </button>
                      <button
                        className="w-full px-4 py-3 text-left hover:bg-red-50 transition-colors text-red-600 hover:text-red-700 font-medium border-t border-gray-100"
                        onClick={() => {
                          localStorage.removeItem("token");
                          window.location.href = "/login";
                        }}
                      >
                        Logout
                      </button>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </header>

        {/* Toast Notifications - Fixed Position */}
        <div className="fixed top-20 right-4 z-50 space-y-2">
          {error && (
            <div className="bg-red-500 text-white px-6 py-4 rounded-lg shadow-2xl flex items-center gap-3 min-w-[300px] animate-slideInRight">
              <span className="material-icons text-2xl">error</span>
              <div>
                <p className="font-bold">Error</p>
                <p className="text-sm">{error}</p>
              </div>
            </div>
          )}

          {successMessage && (
            <div className="bg-green-500 text-white px-6 py-4 rounded-lg shadow-2xl flex items-center gap-3 min-w-[300px] animate-slideInRight">
              <span className="material-icons text-2xl">check_circle</span>
              <div>
                <p className="font-bold">Success</p>
                <p className="text-sm">{successMessage}</p>
              </div>
            </div>
          )}
        </div>

        {/* Horizontal Navigation Bar - Sticky at Top */}
        <nav className="bg-gradient-to-r from-purple-600 via-indigo-600 to-purple-700 border-t border-purple-500 shadow-lg sticky top-0 z-40">
          <ul className="flex items-center justify-center gap-2 px-4 w-full flex-wrap py-2">
            <li
              className={`flex items-center gap-2 px-4 py-3 cursor-pointer transition-all duration-300 rounded-lg ${
                activeTab === "dashboard"
                  ? "bg-white text-purple-900 shadow-lg transform scale-105"
                  : "text-white hover:bg-purple-700"
              }`}
              onClick={() => setActiveTab("dashboard")}
            >
              <span className="material-icons text-lg">dashboard</span>
              <span className="font-semibold text-sm">Dashboard</span>
            </li>
            <li
              className={`flex items-center gap-2 px-4 py-3 cursor-pointer transition-all duration-300 rounded-lg ${
                activeTab === "pending-requests"
                  ? "bg-white text-purple-900 shadow-lg transform scale-105"
                  : "text-white hover:bg-purple-700"
              }`}
              onClick={() => setActiveTab("pending-requests")}
            >
              <span className="material-icons text-lg">pending_actions</span>
              <span className="font-semibold text-sm">Pending Requests</span>
            </li>
            <li
              className={`flex items-center gap-2 px-4 py-3 cursor-pointer transition-all duration-300 rounded-lg ${
                activeTab === "all-records"
                  ? "bg-white text-purple-900 shadow-lg transform scale-105"
                  : "text-white hover:bg-purple-700"
              }`}
              onClick={() => setActiveTab("all-records")}
            >
              <span className="material-icons text-lg">storage</span>
              <span className="font-semibold text-sm">All Records</span>
            </li>
            <li
              className={`flex items-center gap-2 px-4 py-3 cursor-pointer transition-all duration-300 rounded-lg ${
                activeTab === "available-pets"
                  ? "bg-white text-purple-900 shadow-lg transform scale-105"
                  : "text-white hover:bg-purple-700"
              }`}
              onClick={() => setActiveTab("available-pets")}
            >
              <span className="material-icons text-lg">pets</span>
              <span className="font-semibold text-sm">Available Pets</span>
            </li>
            <li
              className={`flex items-center gap-2 px-4 py-3 cursor-pointer transition-all duration-300 rounded-lg ${
                activeTab === "search"
                  ? "bg-white text-purple-900 shadow-lg transform scale-105"
                  : "text-white hover:bg-purple-700"
              }`}
              onClick={() => setActiveTab("search")}
            >
              <span className="material-icons text-lg">search</span>
              <span className="font-semibold text-sm">Search</span>
            </li>
            <li
              className={`flex items-center gap-2 px-4 py-3 cursor-pointer transition-all duration-300 rounded-lg ${
                activeTab === "feedbacks"
                  ? "bg-white text-purple-900 shadow-lg transform scale-105"
                  : "text-white hover:bg-purple-700"
              }`}
              onClick={() => setActiveTab("feedbacks")}
            >
              <span className="material-icons text-lg">chat</span>
              <span className="font-semibold text-sm">Feedbacks</span>
            </li>
            <li
              className={`flex items-center gap-2 px-4 py-3 cursor-pointer transition-all duration-300 rounded-lg ${
                activeTab === "notifications"
                  ? "bg-white text-purple-900 shadow-lg transform scale-105"
                  : "text-white hover:bg-purple-700"
              }`}
              onClick={() => setActiveTab("notifications")}
            >
              <span className="material-icons text-lg">notifications</span>
              <span className="font-semibold text-sm">Notifications</span>
            </li>
          </ul>
        </nav>

        {/* Main Content Container */}
        <div
          className={`overflow-y-auto ${
            isDarkMode ? "bg-slate-900" : "bg-purple-100"
          }`}
          style={{ height: "calc(100vh - 160px)", backgroundImage: isDarkMode ? "none" : "url('/new-background.jpg')", backgroundSize: "cover", backgroundPosition: "center", backgroundBlendMode: "soft-light" }}
        >
          <div className="relative z-10 w-full px-0 py-8">
            <main>
              {error && (
                <div className="bg-red-50 border-l-4 border-red-500 p-4 mb-6 rounded-r-lg">
                  <p className="text-red-700 font-medium">{error}</p>
                </div>
              )}
              {successMessage && (
                <div className="bg-green-50 border-l-4 border-green-500 p-4 mb-6 rounded-r-lg">
                  <p className="text-green-700 font-medium">{successMessage}</p>
                </div>
              )}

              {/* Dashboard Overview */}
              {activeTab === "dashboard" && (
                <div
                  className={`mx-2 sm:mx-4 md:mx-6 lg:mx-8 rounded-2xl shadow-xl p-8 border-2 transition-colors duration-300 ${
                    isDarkMode
                      ? "bg-gradient-to-br from-gray-800 to-purple-900/50 border-purple-700"
                      : "bg-gradient-to-br from-white to-purple-50 border-purple-200"
                  }`}
                >
                  <h2 className="text-2xl font-bold mb-6 flex items-center gap-3">
                    <span
                      className={`material-icons text-3xl ${
                        isDarkMode ? "text-purple-400" : "text-purple-600"
                      }`}
                    >
                      dashboard
                    </span>
                    <span className="bg-gradient-to-r from-purple-600 via-pink-500 to-purple-400 bg-clip-text text-transparent">
                      DASHBOARD OVERVIEW
                    </span>
                  </h2>

                  {/* Stats Grid */}
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-2 mb-8 justify-items-start">
                    {/* Pending Requests */}
                    <div
                      className={`rounded-xl p-6 border-2 hover:shadow-lg transition-all cursor-pointer ${
                        isDarkMode
                          ? "bg-gradient-to-br from-orange-900/40 to-orange-800/40 border-orange-700"
                          : "bg-gradient-to-br from-orange-50 to-orange-100 border-orange-200"
                      }`}
                      onClick={() => setActiveTab("pending-requests")}
                    >
                      <div className="flex items-center justify-between mb-2">
                        <span
                          className={`material-icons text-4xl ${
                            isDarkMode ? "text-orange-400" : "text-orange-600"
                          }`}
                        >
                          pending_actions
                        </span>
                        <span
                          className={`text-3xl font-bold ${
                            isDarkMode ? "text-orange-400" : "text-orange-600"
                          }`}
                        >
                          {dashboardStats?.pending?.total ||
                            pendingLostReports.length +
                              pendingFoundReports.length +
                              pendingAdoptionRequests.length +
                              pendingAdoptionPosts.length}
                        </span>
                      </div>
                      <h3
                        className={`text-sm font-semibold uppercase tracking-wide ${
                          isDarkMode ? "text-gray-300" : "text-gray-600"
                        }`}
                      >
                        Total Pending Requests
                      </h3>
                      <p
                        className={`text-xs mt-2 ${
                          isDarkMode ? "text-gray-400" : "text-gray-500"
                        }`}
                      >
                        Lost:{" "}
                        {dashboardStats?.pending?.lost_reports ||
                          pendingLostReports.length}{" "}
                        | Found:{" "}
                        {dashboardStats?.pending?.found_reports ||
                          pendingFoundReports.length}
                      </p>
                    </div>

                    {/* Lost Pets (Accepted Only) */}
                    <div
                      className="bg-gradient-to-br from-red-50 to-red-100 rounded-xl p-6 border border-red-200 hover:shadow-lg transition-shadow cursor-pointer"
                      onClick={() => {
                        setActiveTab("all-records");
                        setActiveRecordsTab("all-lost");
                      }}
                    >
                      <div className="flex items-center justify-between mb-2">
                        <span className="material-icons text-4xl text-red-600">
                          search
                        </span>
                        <span className="text-3xl font-bold text-red-600">
                          {dashboardStats?.accepted?.lost || allLostPets.length}
                        </span>
                      </div>
                      <h3 className="text-sm font-semibold uppercase tracking-wide ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}">
                        Lost Pets (Accepted)
                      </h3>
                    </div>

                    {/* Found Pets (Accepted Only) */}
                    <div
                      className="bg-gradient-to-br from-green-50 to-green-100 rounded-xl p-6 border border-green-200 hover:shadow-lg transition-shadow cursor-pointer"
                      onClick={() => {
                        setActiveTab("all-records");
                        setActiveRecordsTab("all-found");
                      }}
                    >
                      <div className="flex items-center justify-between mb-2">
                        <span className="material-icons text-4xl text-green-600">
                          pets
                        </span>
                        <span className="text-3xl font-bold text-green-600">
                          {dashboardStats?.accepted?.found ||
                            allFoundPets.length}
                        </span>
                      </div>
                      <h3 className="text-sm font-semibold uppercase tracking-wide ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}">
                        Found Pets (Accepted)
                      </h3>
                    </div>

                    {/* Adopted Pets */}
                    <div
                      className="bg-gradient-to-br from-purple-50 to-purple-100 rounded-xl p-6 border border-purple-200 hover:shadow-lg transition-shadow cursor-pointer"
                      onClick={() => {
                        setActiveTab("all-records");
                        setActiveRecordsTab("all-adopted");
                      }}
                    >
                      <div className="flex items-center justify-between mb-2">
                        <span className="material-icons text-4xl text-purple-600">
                          favorite
                        </span>
                        <span className="text-3xl font-bold text-purple-600">
                          {dashboardStats?.accepted?.adopted ||
                            allAdoptedPets.length}
                        </span>
                      </div>
                      <h3 className="text-sm font-semibold uppercase tracking-wide ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}">
                        Adopted Pets
                      </h3>
                    </div>

                    {/* Available for Adoption */}
                    <div
                      className="bg-gradient-to-br from-purple-200 to-purple-300 dark:from-slate-800 dark:to-purple-900 rounded-xl p-6 border border-blue-100 dark:border-slate-600 hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-1 cursor-pointer"
                      onClick={() => {
                        setActiveTab("all-records");
                        setActiveRecordsTab("available");
                      }}
                    >
                      <div className="flex items-center justify-between mb-2">
                        <span className="material-icons text-4xl text-primary-blue dark:text-purple-300">
                          home
                        </span>
                        <span className="text-3xl font-bold text-gray-800 dark:text-white">
                          {dashboardStats?.accepted?.available ||
                            allAvailablePets.length}
                        </span>
                      </div>
                      <h3 className="text-sm font-semibold uppercase tracking-wide text-gray-700 dark:text-gray-300">
                        Available for Adoption
                      </h3>
                    </div>

                    {/* Total Pets */}
                    <div className="bg-gradient-to-br from-purple-50 to-purple-100 rounded-xl p-6 border-2 border-purple-200 hover:shadow-lg transition-shadow">
                      <div className="flex items-center justify-between mb-2">
                        <span className="material-icons text-4xl text-purple-600">
                          storage
                        </span>
                        <span className="text-3xl font-bold text-purple-700">
                          {dashboardStats?.totals?.pets || 0}
                        </span>
                      </div>
                      <h3 className="text-sm font-semibold text-purple-900 uppercase tracking-wide">
                        Total Pets
                      </h3>
                    </div>

                    {/* Total Reports */}
                    <div className="bg-gradient-to-br from-indigo-50 to-indigo-100 rounded-xl p-6 border-2 border-indigo-200 hover:shadow-lg transition-shadow">
                      <div className="flex items-center justify-between mb-2">
                        <span className="material-icons text-4xl text-indigo-600">
                          description
                        </span>
                        <span className="text-3xl font-bold text-indigo-700">
                          {dashboardStats?.totals?.reports || 0}
                        </span>
                      </div>
                      <h3 className="text-sm font-semibold text-indigo-900 uppercase tracking-wide">
                        Total Reports
                      </h3>
                    </div>

                    {/* Total Adoptions */}
                    <div className="bg-gradient-to-br from-purple-50 to-pink-100 rounded-xl p-6 border-2 border-pink-200 hover:shadow-lg transition-shadow">
                      <div className="flex items-center justify-between mb-2">
                        <span className="material-icons text-4xl text-pink-600">
                          assignment_turned_in
                        </span>
                        <span className="text-3xl font-bold text-pink-700">
                          {dashboardStats?.totals?.adoptions || 0}
                        </span>
                      </div>
                      <h3 className="text-sm font-semibold text-pink-900 uppercase tracking-wide">
                        Total Adoptions
                      </h3>
                    </div>
                  </div>

                  {/* Quick Actions */}
                  <div className="bg-white dark:bg-gray-800 rounded-xl p-6 border-2 border-purple-200">
                    <h3 className="text-xl font-bold text-gray-800 mb-4 flex items-center gap-2">
                      <span className="material-icons text-purple-600">
                        flash_on
                      </span>
                      Quick Actions
                    </h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                      <button
                        onClick={() => setActiveTab("all-records")}
                        className="flex items-center gap-3 px-4 py-3 bg-gradient-to-r from-purple-600 to-indigo-600 text-white rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-200"
                      >
                        <span className="material-icons">folder_open</span>
                        <span className="font-semibold">View Reports</span>
                      </button>
                      <button
                        onClick={() => {
                          setActiveTab("all-records");
                          setActiveRecordsTab("all-adopted");
                        }}
                        className="flex items-center gap-3 px-4 py-3 bg-gradient-to-r from-indigo-500 to-indigo-600 text-white rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-200"
                      >
                        <span className="material-icons">home</span>
                        <span className="font-semibold">Adoptions</span>
                      </button>
                      <button
                        onClick={() => setActiveTab("all-pets")}
                        className="flex items-center gap-3 px-4 py-3 bg-gradient-to-r from-purple-500 to-purple-600 text-white rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-200"
                      >
                        <span className="material-icons">pets</span>
                        <span className="font-semibold">All Pets</span>
                      </button>
                      <button
                        onClick={() => setActiveTab("search")}
                        className="flex items-center gap-3 px-4 py-3 bg-gradient-to-r from-pink-500 to-pink-600 text-white rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-200"
                      >
                        <span className="material-icons">search</span>
                        <span className="font-semibold">Search</span>
                      </button>
                    </div>
                  </div>
                </div>
              )}

              {/* Pending Requests Section (All Types) */}
              {activeTab === "pending-requests" && (
                <div className="mx-2 sm:mx-4 md:mx-6 lg:mx-8 bg-gradient-to-br from-white to-purple-50 rounded-2xl shadow-xl p-8 border-2 border-purple-200">
                  <h2 className="text-2xl font-bold mb-6 flex items-center gap-3">
                    <span className="material-icons text-3xl text-orange-600">
                      pending_actions
                    </span>
                    <span className="bg-gradient-to-r from-orange-600 via-red-600 to-pink-600 bg-clip-text text-transparent">
                      PENDING REQUESTS (NEW)
                    </span>
                  </h2>

                  {/* Sub-tabs for different request types */}
                  <div className="flex gap-2 mb-6 flex-wrap">
                    <button
                      onClick={() => setActivePendingTab("lost-reports")}
                      className={`px-4 py-2 rounded-lg font-semibold transition-all ${
                        activePendingTab === "lost-reports"
                          ? "bg-red-600 text-white shadow-lg"
                          : "bg-white text-gray-600 dark:text-gray-300 hover:bg-red-50"
                      }`}
                    >
                      Lost Reports ({pendingLostReports.length})
                    </button>
                    <button
                      onClick={() => setActivePendingTab("found-reports")}
                      className={`px-4 py-2 rounded-lg font-semibold transition-all ${
                        activePendingTab === "found-reports"
                          ? "bg-green-600 text-white shadow-lg"
                          : "bg-white text-gray-600 dark:text-gray-300 hover:bg-green-50"
                      }`}
                    >
                      Found Reports ({pendingFoundReports.length})
                    </button>
                    <button
                      onClick={() => setActivePendingTab("adoption-requests")}
                      className={`px-4 py-2 rounded-lg font-semibold transition-all ${
                        activePendingTab === "adoption-requests"
                          ? "bg-purple-600 text-white shadow-lg"
                          : "bg-white text-gray-600 dark:text-gray-300 hover:bg-purple-50"
                      }`}
                    >
                      Adoption Requests ({pendingAdoptionRequests.length})
                    </button>
                    <button
                      onClick={() => setActivePendingTab("adoption-posts")}
                      className={`px-4 py-2 rounded-lg font-semibold transition-all ${
                        activePendingTab === "adoption-posts"
                          ? "bg-pink-600 text-white shadow-lg"
                          : "bg-white text-gray-600 dark:text-gray-300 hover:bg-pink-50"
                      }`}
                    >
                      Post to Adopt ({pendingAdoptionPosts.length})
                    </button>
                  </div>

                  {/* Lost Pet Reports */}
                  {activePendingTab === "lost-reports" && (
                    <div className="mb-8">
                      <h3 className="text-xl font-bold mb-4 text-red-600 flex items-center gap-2">
                        <span className="material-icons">report</span>
                        Lost Pet Reports ({pendingLostReports.length})
                      </h3>
                      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2 justify-items-start">
                        {pendingLostReports.length > 0 ? (
                          pendingLostReports.map((report) => (
                            <div
                              key={report.id}
                              className="max-w-sm bg-gradient-to-br from-white to-blue-50 dark:from-slate-800 dark:to-blue-900 rounded-2xl shadow-lg overflow-hidden hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 border border-blue-200 dark:border-blue-700"
                            >
                              <div className="relative h-56 overflow-hidden">
                                <img
                                  src={getImageUrl(report.photo)}
                                  alt={report.pet_name}
                                  className="w-full h-full object-cover"
                                  onError={(e) => {
                                    e.target.src = "/default-pet.png";
                                  }}
                                />
                                <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/70 to-transparent p-4">
                                  <h3 className="text-white font-bold text-lg">
                                    {report.pet_name}
                                  </h3>
                                </div>
                                <div className="absolute top-2 right-2">
                                  <span className="px-3 py-1 bg-yellow-500 text-white text-xs font-bold rounded-full shadow-lg">
                                    PENDING
                                  </span>
                                </div>
                              </div>
                              <div className="p-5 space-y-3">
                                <div className="inline-block px-3 py-1 bg-purple-100 text-purple-700 rounded-full text-sm font-semibold">
                                  {report.animal_type}
                                </div>
                                <div className="space-y-2">
                                  {report.pet_breed && (
                                    <span className="block text-gray-700 dark:text-gray-200 text-sm">
                                      <span className="font-semibold">
                                        Breed:
                                      </span>{" "}
                                      {report.pet_breed}
                                    </span>
                                  )}
                                  {report.pet_location && (
                                    <span className="flex items-center gap-1 text-gray-700 dark:text-gray-200 text-sm">
                                      <span className="material-icons text-xs">
                                        location_on
                                      </span>
                                      {report.pet_location}
                                    </span>
                                  )}
                                  <span className="block text-gray-600 dark:text-gray-300 text-sm">
                                    <span className="font-semibold">By:</span>{" "}
                                    {report.owner_username || "Unknown"}
                                  </span>
                                </div>
                                <div className="flex items-center justify-between pt-2 border-t border-gray-100">
                                  <span className="text-xs text-gray-500 dark:text-gray-400">
                                    {new Date(
                                      report.created_at
                                    ).toLocaleDateString()}
                                  </span>
                                </div>
                                <div className="flex gap-2 pt-3">
                                  <button
                                    onClick={() =>
                                      viewDetails(report, "report")
                                    }
                                    className="flex-1 px-3 py-2 bg-gradient-to-r from-purple-600 to-indigo-600 text-white rounded-lg hover:shadow-lg transform hover:scale-105 transition-all duration-200 font-semibold flex items-center justify-center gap-1"
                                  >
